1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.DisposableEmailDomains;
13	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
14	import org.springframework.samples.petclinic.util.IdentityKeyUtils;
15	
16	import java.time.LocalDate;
17	import java.time.Month;
18	import java.time.Period;
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Map;
22	
23	/**
24	 * Maps Owner & OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "displayName",
30	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
31	    @Mapping(target = "initials",
32	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
33	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
34	    @Mapping(target = "membershipPoints",
35	        expression = "java(toMembershipPoints(owner))")
36	    @Mapping(target = "membershipLevel",
37	        expression = "java(toMembershipLevel(owner))")
38	    @Mapping(target = "locality",
39	        expression = "java(toLocality(owner))")
40	    @Mapping(target = "ownerSegment",
41	        expression = "java(toOwnerSegment(owner))")
42	    @Mapping(target = "timezone",
43	        expression = "java(toTimezone(owner))")
44	    @Mapping(target = "contactPreference",
45	        expression = "java(toContactPreference(owner))")
46	    @Mapping(target = "apiVersion",
47	        expression = "java(IDENTITY_API_VERSION)")
48	    @Mapping(target = "identity",
49	        expression = "java(toIdentity(owner))")
50	    @Mapping(target = "ageBand",
51	        expression = "java(toAgeBand(owner))")
52	    @Mapping(target = "telephoneDisplay",
53	        expression = "java(toTelephoneDisplay(owner))")
54	    @Mapping(target = "salutation",
55	        expression = "java(toSalutation(owner))")
56	    @Mapping(target = "fiscalYear",
57	        expression = "java(toFiscalYear(owner))")
58	    @Mapping(target = "selfLink",
59	        expression = "java(toSelfLink(owner))")
60	    @Mapping(target = "riskFlag",
61	        expression = "java(toRiskFlag(owner))")
62	    OwnerDto toOwnerDto(Owner owner);
63	
64	    /**
65	     * Derive an owner's risk flag: {@code true} when the owner warrants a manual risk review, defined
66	     * as the logical OR of three conditions — the owner is a possible duplicate
67	     * ({@code possibleDuplicate} is true), the owner's email domain is disposable-adjacent (see
68	     * {@link #hasDisposableAdjacentEmail(Owner)}), or the owner's city is over its soft capacity
69	     * ({@code capacityWarning} is true). Otherwise {@code false}. Derived at read time.
70	     */
71	    default Boolean toRiskFlag(Owner owner) {
72	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
73	            || Boolean.TRUE.equals(owner.getCapacityWarning())
74	            || hasDisposableAdjacentEmail(owner);
75	    }
76	
77	    /**
78	     * Whether the owner's email domain is disposable-adjacent: a domain that is not itself a
79	     * whole-blocklisted disposable domain (those are rejected at creation) but shares a known
80	     * disposable provider's second-level label — i.e. one of the domain's dot-separated labels equals a
81	     * label in {@link DisposableEmailDomains#BASE_LABELS}. This catches subdomains of a disposable provider
82	     * (e.g. {@code sub.mailinator.com}) and the same base under a different TLD (e.g.
83	     * {@code mailinator.net}), while a merely similar label (e.g. {@code mymailinator.com}) is not
84	     * matched. Returns {@code false} when the owner has no email or the value carries no domain.
85	     */
86	    default boolean hasDisposableAdjacentEmail(Owner owner) {
87	        if (!hasEmail(owner)) {
88	            return false;
89	        }
90	        String email = owner.getEmail();
91	        int at = email.lastIndexOf('@');
92	        if (at < 0 || at == email.length() - 1) {
93	            return false;
94	        }
95	        String domain = email.substring(at + 1).toLowerCase();
96	        for (String label : domain.split("\\.")) {
97	            if (DisposableEmailDomains.BASE_LABELS.contains(label)) {
98	                return true;
99	            }
100	        }
101	        return false;
102	    }
103	
104	    /**
105	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
106	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
107	     * then absent from the DTO).
108	     */
109	    default String toSelfLink(Owner owner) {
110	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
111	    }
112	
113	    /**
114	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
115	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
116	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
117	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
118	     * 2026). This is the single source of truth for the fiscal year used both when the create endpoint
119	     * bakes the FY segment into the member id (see {@code OwnerRestControllerV1.memberIdFor}) and when
120	     * the DTO's {@code fiscalYear} falls back to the registration date for a legacy record.
121	     *
122	     * @param date the date to resolve, on a business day
123	     * @return the calendar year in which that date's fiscal year ends
124	     */
125	    static int fiscalYear(LocalDate date) {
126	        int year = date.getYear();
127	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
128	    }
129	
130	    /**
131	     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
132	     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
133	     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
134	     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
135	     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
136	     * {@code null} when neither is present (the field is then absent from the DTO).
137	     */
138	    default String toFiscalYear(Owner owner) {
139	        String base = memberIdBase(owner.getMemberId());
140	        if (base != null) {
141	            return "FY" + memberIdFyDigits(base);
142	        }
143	        LocalDate registrationDate = owner.getRegistrationDate();
144	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
145	    }
146	
147	    /**
148	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
149	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
150	     * just the last name.
151	     */
152	    default String toSalutation(Owner owner) {
153	        String lastName = owner.getLastName();
154	        String title = owner.getTitle();
155	        if (title == null || title.isBlank()) {
156	            return lastName;
157	        }
158	        return title + " " + lastName;
159	    }
160	
161	    /**
162	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
163	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
164	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
165	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
166	     */
167	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
168	        LocalDate birthDate = owner.getBirthDate();
169	        if (birthDate == null) {
170	            return null;
171	        }
172	        LocalDate reference = owner.getRegistrationDate() != null
173	            ? owner.getRegistrationDate() : LocalDate.now();
174	        int age = Period.between(birthDate, reference).getYears();
175	        if (age < 18) {
176	            return OwnerDto.AgeBandEnum.MINOR;
177	        }
178	        if (age < 65) {
179	            return OwnerDto.AgeBandEnum.ADULT;
180	        }
181	        return OwnerDto.AgeBandEnum.SENIOR;
182	    }
183	
184	    /**
185	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
186	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
187	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
188	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
189	     *
190	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
191	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
192	     * code, a two-digit country code is assumed (the most common length).
193	     */
194	    default String toTelephoneDisplay(Owner owner) {
195	        String telephone = owner.getTelephone();
196	        if (telephone == null || !telephone.startsWith("+")) {
197	            return telephone;
198	        }
199	        String digits = telephone.substring(1);
200	        String code = E164PhoneNumbers.countryCode(digits)
201	            .filter(c -> digits.length() > c.length())
202	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
203	        String national = digits.substring(code.length());
204	        StringBuilder sb = new StringBuilder("+").append(code);
205	        for (int i = 0; i < national.length(); i += 3) {
206	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
207	        }
208	        return sb.toString();
209	    }
210	
211	    /**
212	     * The fixed trailing-segment widths of a member id base {@code '<REGION><FY><HASH8><CHK>'}: FY is 2
213	     * digits, HASH8 is 8 hex characters and CHK is 1 digit, so the last {@link #MEMBER_ID_SUFFIX_WIDTH}
214	     * characters are the {@code <FY><HASH8><CHK>} suffix and REGION is the variable-width remainder in
215	     * front of it. This is the single place the layout is encoded; the position arithmetic in
216	     * {@link #memberIdFyDigits(String)} derives from these, and it must stay in step with how
217	     * {@code OwnerRestControllerV1.memberIdFor} assembles the id.
218	     */
219	    int FY_WIDTH = 2;
220	    int HASH8_WIDTH = 8;
221	    int CHK_WIDTH = 1;
222	    int MEMBER_ID_SUFFIX_WIDTH = FY_WIDTH + HASH8_WIDTH + CHK_WIDTH;
223	
224	    /**
225	     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
226	     * suffix, or {@code null} when the owner has no (well-formed) member id yet — i.e. one long enough to
227	     * carry a non-empty REGION in front of the fixed {@link #MEMBER_ID_SUFFIX_WIDTH}-character suffix.
228	     * Use {@link #memberIdFyDigits(String)} to decode its FY segment.
229	     */
230	    private static String memberIdBase(String memberId) {
231	        if (memberId == null) {
232	            return null;
233	        }
234	        int dash = memberId.indexOf('-');
235	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
236	        return base.length() > MEMBER_ID_SUFFIX_WIDTH ? base : null;
237	    }
238	
239	    /**
240	     * The two-digit {@code <FY>} segment of a (non-null, well-formed) member id base: the characters
241	     * immediately preceding the trailing HASH8 and CHK segments.
242	     */
243	    private static String memberIdFyDigits(String base) {
244	        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
245	        return base.substring(fyEnd - FY_WIDTH, fyEnd);
246	    }
247	
248	    /**
249	     * The identity API version carried by the owner response. Version 2 groups the identifiers under the
250	     * nested {@code identity} object and derives them with the version-2 algorithm (see
251	     * {@link IdentityKeyUtils#IDENTITY_VERSION_TAG}).
252	     */
253	    int IDENTITY_API_VERSION = 2;
254	
255	    /**
256	     * Groups the owner's version-2 identifiers — the member id, household id and identity key — under the
257	     * nested {@code identity} object of the DTO. Each identifier is derived by the version-2 algorithm
258	     * (see {@link IdentityKeyUtils#IDENTITY_VERSION_TAG}); the identity key is (re)derived here from the same single
259	     * source of truth used by the create endpoint's duplicate check, while the member id and household id
260	     * are the values frozen on the owner at creation.
261	     */
262	    default OwnerIdentityDto toIdentity(Owner owner) {
263	        OwnerIdentityDto identity = new OwnerIdentityDto();
264	        identity.setMemberId(owner.getMemberId());
265	        identity.setHouseholdId(owner.getHouseholdId());
266	        identity.setIdentityKey(toIdentityKey(owner));
267	        return identity;
268	    }
269	
270	    /**
271	     * Derive an owner's version-2 duplicate-detection identity key: the lower-case SHA-256 hex digest
272	     * (64 characters) of the normalized E.164 telephone, the lower-cased email (empty when none), the
273	     * American Soundex code of the last name and the fixed {@link IdentityKeyUtils#IDENTITY_VERSION_TAG version tag},
274	     * joined with {@code '|'}. Mixing in the version tag means no key produced under version 1 is
275	     * produced again. Two owners are duplicates only when their whole identity keys are equal.
276	     *
277	     * <p>This is the single source of truth for the key: it is both returned on the DTO (under
278	     * {@code identity}) and used by the create endpoint's 409 duplicate check, so the value clients see
279	     * is exactly the value that governs rejection. The "email present" rule reuses
280	     * {@link #hasEmail(Owner)}, and the Soundex and hashing come from {@link IdentityKeyUtils}, the same
281	     * helpers the soft-match uses.
282	     */
283	    default String toIdentityKey(Owner owner) {
284	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
285	        String email = hasEmail(owner) ? owner.getEmail() : "";
286	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
287	        return IdentityKeyUtils.sha256Hex(
288	            telephone + "|" + email + "|" + soundex + "|" + IdentityKeyUtils.IDENTITY_VERSION_TAG);
289	    }
290	
291	    /**
292	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
293	     * for the "is an email present" rule shared by the derived fields below.
294	     */
295	    default boolean hasEmail(Owner owner) {
296	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
297	    }
298	
299	    /**
300	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
301	     * otherwise 'PHONE'.
302	     */
303	    default String toContactPreference(Owner owner) {
304	        return hasEmail(owner) ? "EMAIL" : "PHONE";
305	    }
306	
307	    /**
308	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
309	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
310	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
311	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
312	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
313	     * and no namesakes in a single-member household scores 3 points.
314	     */
315	    default Integer toMembershipPoints(Owner owner) {
316	        int points = 0;
317	        if (hasEmail(owner)) {
318	            points += 2;
319	        }
320	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
321	        if (noNamesakes) {
322	            points += 1;
323	        }
324	        if (hasHouseholdBonus(owner)) {
325	            points += 2;
326	        }
327	        if (hasTenureBonus(owner)) {
328	            points += 3;
329	        }
330	        return points;
331	    }
332	
333	    /**
334	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
335	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
336	     * Returns {@code false} when no household size is present (e.g. legacy records).
337	     */
338	    default boolean hasHouseholdBonus(Owner owner) {
339	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
340	    }
341	
342	    /**
343	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
344	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
345	     * or more.
346	     *
347	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
348	     * owner's membership level cannot exceed one above the current maximum membership level among their
349	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
350	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
351	     * member, or a legacy record) the uncapped level stands.
352	     */
353	    default Integer toMembershipLevel(Owner owner) {
354	        int level = uncappedMembershipLevel(owner);
355	        Integer cap = owner.getMembershipLevelCap();
356	        if (cap != null && level > cap) {
357	            return cap;
358	        }
359	        return level;
360	    }
361	
362	    /**
363	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
364	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
365	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
366	     */
367	    default Integer uncappedMembershipLevel(Owner owner) {
368	        int points = toMembershipPoints(owner);
369	        if (points <= 1) {
370	            return 1;
371	        }
372	        if (points <= 3) {
373	            return 2;
374	        }
375	        if (points <= 5) {
376	            return 3;
377	        }
378	        return 4;
379	    }
380	
381	    /**
382	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
383	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
384	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
385	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
386	     * no registration date is present.
387	     */
388	    default boolean hasTenureBonus(Owner owner) {
389	        LocalDate registrationDate = owner.getRegistrationDate();
390	        if (registrationDate == null) {
391	            return false;
392	        }
393	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
394	    }
395	
396	    /**
397	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
398	     */
399	    Map<String, String> CITY_REGION = Map.of(
400	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
401	
402	    /**
403	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
404	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
405	     * inclusive.
406	     */
407	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
408	        "NSW", new int[] {2000, 2099},
409	        "VIC", new int[] {3000, 3099},
410	        "QLD", new int[] {4000, 4099});
411	
412	    /**
413	     * Derive an owner's locality: the plain, unversioned region code, derived directly from the postcode
414	     * (falling back to the fixed city-to-region table, else {@code 'UNKNOWN'}; see
415	     * {@link #regionOf(Owner)}). The locality is a user-facing field, not an identifier, so it must stay
416	     * the plain region code (e.g. {@code 'NSW'}) and must never carry the {@link IdentityKeyUtils#IDENTITY_VERSION_TAG}
417	     * that the version-2 algorithm mixes into the region code <em>inside</em> the member id. It is
418	     * therefore recomputed from the owner rather than read back out of the (now version-2-tagged)
419	     * member id.
420	     */
421	    default String toLocality(Owner owner) {
422	        return regionOf(owner);
423	    }
424	
425	    /**
426	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
427	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
428	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
429	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
430	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
431	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
432	     * {@code 'REGIONAL'}.
433	     */
434	    default String toOwnerSegment(Owner owner) {
435	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
436	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
437	        return tier + "_" + area;
438	    }
439	
440	    /**
441	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
442	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
443	     */
444	    Map<String, String> REGION_TIMEZONE = Map.of(
445	        "NSW", "Australia/Sydney",
446	        "VIC", "Australia/Melbourne",
447	        "QLD", "Australia/Brisbane");
448	
449	    /**
450	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
451	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
452	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
453	     */
454	    default String toTimezone(Owner owner) {
455	        return REGION_TIMEZONE.get(toLocality(owner));
456	    }
457	
458	    /**
459	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
460	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
461	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
462	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This plain region code is both
463	     * the owner's user-facing {@link #toLocality(Owner) locality} and, with the
464	     * {@link IdentityKeyUtils#IDENTITY_VERSION_TAG 'V2' version tag} mixed in, the region code baked into the leading
465	     * {@code <REGION>} segment of a new owner's member id.
466	     */
467	    default String regionOf(Owner owner) {
468	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
469	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
470	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
471	        String postcode = owner.getPostcode();
472	        if (postcode != null) {
473	            try {
474	                int value = Integer.parseInt(postcode.trim());
475	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
476	                    int[] range = entry.getValue();
477	                    if (value >= range[0] && value <= range[1]) {
478	                        return entry.getKey();
479	                    }
480	                }
481	            }
482	            catch (NumberFormatException ignored) {
483	                // Non-numeric postcode: fall back to the city table below.
484	            }
485	        }
486	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
487	    }
488	
489	    Owner toOwner(OwnerDto ownerDto);
490	
491	    @Mapping(target = "id", ignore = true)
492	    @Mapping(target = "pets", ignore = true)
493	    Owner toOwner(OwnerFieldsDto ownerDto);
494	
495	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
496	
497	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
498	
499	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
500	        OwnerPageDto ownerPageDto = new OwnerPageDto();
501	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
502	        ownerPageDto.setPage(ownerPage.getNumber());
