19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Helpers backing the owner duplicate-detection identity key. The identity key is the lower-case
26	 * SHA-256 hex of the owner's normalized telephone, lower-cased email and the American Soundex code of
27	 * the last name, joined with {@code '|'} (see {@code OwnerMapper.toIdentityKey}). Both the key itself
28	 * and the soft-match (which compares the Soundex code and postcode) route through this single source of
29	 * truth, so the two cannot diverge.
30	 *
31	 * <p>These are deliberately plain {@code static} utilities in their own class rather than default
32	 * methods on the MapStruct owner mapper: a {@code String -> String} mapper method would be picked up by
33	 * MapStruct as an implicit type conversion and wrongly applied to unrelated String properties.
34	 */
35	public final class IdentityKeyUtils {
36	
37	    /**
38	     * The fixed version tag mixed into every derived owner identifier — the member id's region code, the
39	     * household id and the identity key — to produce the version-2 identity. Because the tag becomes part
40	     * of each identifier's pre-image (or, for the member id, its literal region segment), no value
41	     * produced under version 1 is produced again. This is the single source of truth shared by every
42	     * layer that derives an identifier; it is deliberately absent from the user-facing region derivations
43	     * (locality, timezone and the owner segment's derived region), which keep the plain region code.
44	     */
45	    public static final String IDENTITY_VERSION_TAG = "V2";
46	
47	    private IdentityKeyUtils() {
48	    }
49	
50	    /**
51	     * Computes the American Soundex code of a name: the (upper-cased) first letter followed by three
52	     * digits, zero-padded or truncated to exactly four characters. Consonants are coded 1-6 by group;
